def search_servers(query, n=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0063000" if __import__("os").path.isdir("./environment_mix/0063000") else "/app/database")

    def _load(nm):
        try:
            with open(os.path.join(_DB, nm), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(nm, d):
        with open(os.path.join(_DB, nm), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(dt):
        if not isinstance(dt, str) or not dt:
            return None
        try:
            if dt.endswith("Z"):
                return datetime.datetime.fromisoformat(dt[:-1])
            return datetime.datetime.fromisoformat(dt)
        except Exception:
            return None

    def _new_id(prefix):
        # readable, stable-enough for local store
        return f"{prefix}_{int(time.time() * 1000)}_{os.getpid()}"

    t0 = time.time()
    status_code = "succeeded"
    error_obj = None
    saved_query_row = None

    # Validate input
    if not isinstance(query, str) or query.strip() == "":
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    q = query  # must persist exactly as provided
    if n is None:
        nn = 3
    else:
        if not isinstance(n, (int, float)) or isinstance(n, bool):
            return _err("VALIDATION_ERROR", "n must be a number between 1 and 5")
        if int(n) != n:
            # accept floats only if whole-number
            return _err("VALIDATION_ERROR", "n must be an integer between 1 and 5")
        nn = int(n)
    if nn < 1 or nn > 5:
        return _err("VALIDATION_ERROR", "n must be between 1 and 5")

    # Create search_queries row (received -> running -> succeeded/failed), always persisted
    queries = _load("search_queries.json")
    now = _now_iso()
    qid = _new_id("sq")
    saved_query_row = {
        "id": qid,
        "query": q,
        "n": nn,
        "search_mode": "hybrid",
        "status": "received",
        "result_server_ids": None,
        "latency_ms": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    queries.append(saved_query_row)
    _save("search_queries.json", queries)

    # Mark running
    saved_query_row["status"] = "running"
    saved_query_row["updated_at"] = _now_iso()
    _save("search_queries.json", queries)

    try:
        servers = _load("mcp_servers.json")
        tools = _load("mcp_tools.json")

        # only active servers by default (policy: exclude deprecated unless internal override; none here)
        active_servers = [s for s in servers if isinstance(s, dict) and s.get("status") == "active"]

        # Hybrid-ish scoring: token overlap + substring hits across qualified_name/display_name/description/tags/owner
        q_norm = q.strip().lower()
        q_tokens = [t for t in re.split(r"[^a-z0-9]+", q_norm) if t]
        q_token_set = set(q_tokens)

        def field_text(srv):
            parts = []
            for k in ("qualified_name", "display_name", "description", "owner"):
                v = srv.get(k)
                if isinstance(v, str):
                    parts.append(v.lower())
            tg = srv.get("tags")
            if isinstance(tg, list):
                parts.append(" ".join([str(x).lower() for x in tg]))
            return " ".join(parts)

        def score(srv):
            text = field_text(srv)
            sc = 0.0
            if q_norm and q_norm in text:
                sc += 5.0
            # token overlap
            if q_token_set:
                text_tokens = set([t for t in re.split(r"[^a-z0-9]+", text) if t])
                overlap = len(q_token_set.intersection(text_tokens))
                sc += overlap * 1.0
                # prefix bonus for qualified_name/display_name
                qn = (srv.get("qualified_name") or "").lower()
                dn = (srv.get("display_name") or "").lower()
                for tok in q_token_set:
                    if qn.startswith(tok):
                        sc += 1.5
                    if dn.startswith(tok):
                        sc += 1.0
            # tag exact match bonus
            tags = srv.get("tags") if isinstance(srv.get("tags"), list) else []
            tags_l = set([str(x).lower() for x in tags])
            for tok in q_token_set:
                if tok in tags_l:
                    sc += 1.0
            # slight recency tie-breaker: newer updated_at ranks a bit higher
            upd = _parse_iso(srv.get("updated_at"))
            if upd:
                age_days = max(0.0, (datetime.datetime.utcnow() - upd).total_seconds() / 86400.0)
                sc += max(0.0, 0.25 - min(0.25, age_days * 0.001))
            return sc

        scored = [(score(s), s) for s in active_servers]
        scored.sort(key=lambda x: (x[0], _parse_iso((x[1] or {}).get("updated_at")) or datetime.datetime.min), reverse=True)

        top = [s for sc, s in scored if sc > 0.0]
        if len(top) < nn:
            # if nothing scored, still allow returning top recent active servers as fallback
            if not top:
                top = [s for _, s in scored]
        top = top[:nn]

        # Attach available tools (active/deprecated? "available" => active only)
        tools_by_server = {}
        for t in tools:
            if not isinstance(t, dict):
                continue
            sid = t.get("server_id")
            if not sid:
                continue
            tools_by_server.setdefault(sid, []).append(t)

        results = []
        result_ids = []
        for s in top:
            sid = s.get("id")
            if sid:
                result_ids.append(sid)
            srv_tools = []
            for t in tools_by_server.get(sid, []):
                if t.get("status") != "active":
                    continue
                srv_tools.append(
                    {
                        "id": t.get("id"),
                        "name": t.get("name"),
                        "description": t.get("description"),
                        "is_streaming": t.get("is_streaming"),
                        "status": t.get("status"),
                        "input_schema": t.get("input_schema"),
                        "output_schema": t.get("output_schema"),
                        "created_at": t.get("created_at"),
                        "updated_at": t.get("updated_at"),
                    }
                )

            results.append(
                {
                    "id": s.get("id"),
                    "qualified_name": s.get("qualified_name"),
                    "display_name": s.get("display_name"),
                    "description": s.get("description"),
                    "homepage_url": s.get("homepage_url"),
                    "repo_url": s.get("repo_url"),
                    "transport": s.get("transport"),
                    "endpoint_url": s.get("endpoint_url"),
                    "tags": s.get("tags"),
                    "owner": s.get("owner"),
                    "icon_url": s.get("icon_url"),
                    "status": s.get("status"),
                    "last_indexed_at": s.get("last_indexed_at"),
                    "created_at": s.get("created_at"),
                    "updated_at": s.get("updated_at"),
                    "tools": srv_tools,
                }
            )

        latency_ms = int((time.time() - t0) * 1000)

        # Update search_queries row to succeeded
        saved_query_row["status"] = "succeeded"
        saved_query_row["result_server_ids"] = result_ids
        saved_query_row["latency_ms"] = latency_ms
        saved_query_row["updated_at"] = _now_iso()
        _save("search_queries.json", queries)

        return {
            "object": "toolbox.search_results",
            "query_id": qid,
            "query": q,
            "n": nn,
            "results": results,
            "latency_ms": latency_ms,
        }
    except Exception as e:
        # Update search_queries row to failed (do not hide unexpected error details completely)
        latency_ms = int((time.time() - t0) * 1000)
        queries = _load("search_queries.json")
        # locate by id; if absent, nothing we can do
        for row in queries:
            if isinstance(row, dict) and row.get("id") == qid:
                row["status"] = "failed"
                row["latency_ms"] = latency_ms
                row["error_code"] = "INTERNAL_ERROR"
                row["error_message"] = str(e)
                row["updated_at"] = _now_iso()
                break
        _save("search_queries.json", queries)
        return _err("CONFLICT", "search pipeline failed", error_code="INTERNAL_ERROR", error_message=str(e))

def use_tool(qualifiedName, parameters, **_extra):
    import json, os, datetime, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0063000" if __import__("os").path.isdir("./environment_mix/0063000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _lat_ms():
        ms = int((time.time() - t0) * 1000)
        return ms if ms >= 0 else 0

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int(time.time() * 1000)
        r = random.getrandbits(40)
        s = n ^ r
        out = []
        for _ in range(12):
            out.append(alphabet[s % 32])
            s //= 32
        return f"{prefix}_01J{''.join(reversed(out))}"

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None

    def _validate_input_schema(schema, args_obj):
        # Best-effort JSON Schema (draft-07 subset). Unknown keywords ignored.
        if schema is None:
            return True, None
        if not isinstance(schema, dict):
            return True, None

        def _type_ok(t, v):
            if t == "object":
                return isinstance(v, dict)
            if t == "array":
                return isinstance(v, list)
            if t == "string":
                return isinstance(v, str)
            if t == "boolean":
                return isinstance(v, bool)
            if t == "number":
                return isinstance(v, (int, float)) and not isinstance(v, bool)
            if t == "integer":
                return isinstance(v, int) and not isinstance(v, bool)
            if t == "null":
                return v is None
            return True

        def _walk(sch, val, path):
            if not isinstance(sch, dict):
                return True, None

            if "type" in sch:
                tt = sch["type"]
                if isinstance(tt, list):
                    if not any(_type_ok(t, val) for t in tt):
                        return False, f"{path} must be of type {tt}"
                else:
                    if not _type_ok(tt, val):
                        return False, f"{path} must be of type {tt}"

            if "enum" in sch and isinstance(sch["enum"], list):
                if val not in sch["enum"]:
                    return False, f"{path} must be one of {sch['enum']}"

            if isinstance(val, str):
                if "minLength" in sch and isinstance(sch["minLength"], int):
                    if len(val) < sch["minLength"]:
                        return False, f"{path} must have minLength {sch['minLength']}"
                if "maxLength" in sch and isinstance(sch["maxLength"], int):
                    if len(val) > sch["maxLength"]:
                        return False, f"{path} must have maxLength {sch['maxLength']}"
                if "pattern" in sch and isinstance(sch["pattern"], str):
                    try:
                        if re.search(sch["pattern"], val) is None:
                            return False, f"{path} must match pattern {sch['pattern']}"
                    except re.error:
                        pass

            if isinstance(val, (int, float)) and not isinstance(val, bool):
                if "minimum" in sch and isinstance(sch["minimum"], (int, float)):
                    if val < sch["minimum"]:
                        return False, f"{path} must be >= {sch['minimum']}"
                if "maximum" in sch and isinstance(sch["maximum"], (int, float)):
                    if val > sch["maximum"]:
                        return False, f"{path} must be <= {sch['maximum']}"

            if isinstance(val, dict):
                props = sch.get("properties")
                req = sch.get("required")
                addl = sch.get("additionalProperties", True)

                if isinstance(req, list):
                    for k in req:
                        if k not in val:
                            return False, f"{path}.{k} is required" if path else f"{k} is required"

                if isinstance(props, dict):
                    for k, sub in props.items():
                        if k in val:
                            ok, em = _walk(sub, val[k], f"{path}.{k}" if path else k)
                            if not ok:
                                return ok, em

                if addl is False and isinstance(props, dict):
                    for k in val.keys():
                        if k not in props:
                            return False, f"{path}.{k} is not allowed" if path else f"{k} is not allowed"

            if isinstance(val, list):
                items = sch.get("items")
                if isinstance(items, dict):
                    for i, it in enumerate(val):
                        ok, em = _walk(items, it, f"{path}[{i}]")
                        if not ok:
                            return ok, em

            return True, None

        return _walk(schema, args_obj, "")

    # -------- Validate input envelope (and reject disallowed fields) --------
    if not isinstance(qualifiedName, str) or not qualifiedName.strip():
        return _err("VALIDATION_ERROR", "qualifiedName is required and must be a non-empty string", field="qualifiedName")
    if not isinstance(parameters, dict):
        return _err("VALIDATION_ERROR", "parameters must be an object", field="parameters")

    allowed_param_keys = {"name", "arguments"}
    for k in parameters.keys():
        if k not in allowed_param_keys:
            return _err("VALIDATION_ERROR", f"parameters contains disallowed field '{k}' (allowed: name, arguments)", field=f"parameters.{k}")

    tool_name = parameters.get("name")
    if not isinstance(tool_name, str) or not tool_name.strip():
        return _err("VALIDATION_ERROR", "parameters.name is required and must be a non-empty string", field="parameters.name")

    arguments = parameters.get("arguments", {})
    if arguments is None:
        arguments = {}
    if not isinstance(arguments, dict):
        return _err("VALIDATION_ERROR", "parameters.arguments must be an object", field="parameters.arguments")

    # -------- Prepare execution log row (must record every call) --------
    execs = _load("tool_executions.json")
    if not isinstance(execs, list):
        execs = []

    now = _now()
    exec_id = _gen_id("mcp_exec")
    created_at = _iso(now)
    started_at = created_at

    execution = {
        "id": exec_id,
        "server_id": None,
        "qualified_name": qualifiedName,
        "tool_id": None,
        "tool_name": tool_name,
        "arguments": arguments,
        "status": "running",
        "request_started_at": started_at,
        "request_finished_at": None,
        "latency_ms": None,
        "response": None,
        "error_code": None,
        "error_message": None,
        "created_at": created_at,
        "updated_at": created_at,
    }

    servers = _load("mcp_servers.json")
    if not isinstance(servers, list):
        servers = []

    tools = _load("mcp_tools.json")
    if not isinstance(tools, list):
        tools = []

    # Resolve server by exact qualified_name match
    server = None
    for s in servers:
        if isinstance(s, dict) and s.get("qualified_name") == qualifiedName:
            server = s
            break

    finished_at = _iso(_now())

    # If server not found / inactive, record FAILED with required fields
    if server is None:
        execution["status"] = "failed"
        execution["request_finished_at"] = finished_at
        execution["latency_ms"] = _lat_ms()
        execution["error_code"] = "SERVER_NOT_FOUND"
        execution["error_message"] = f"Server qualifiedName '{qualifiedName}' not found"
        execution["updated_at"] = finished_at
        execs.append(execution)
        _save("tool_executions.json", execs)
        return _err(
            "NOT_FOUND",
            f"Server qualifiedName '{qualifiedName}' not found (rule: qualifiedName must match an existing active server)",
            error_code="SERVER_NOT_FOUND",
            execution=execution,
        )

    execution["server_id"] = server.get("id")
    server_status = server.get("status")
    if server_status != "active":
        execution["status"] = "failed"
        execution["request_finished_at"] = finished_at
        execution["latency_ms"] = _lat_ms()
        execution["error_code"] = "SERVER_DISABLED"
        execution["error_message"] = f"Server '{qualifiedName}' is not active (status={server_status})"
        execution["updated_at"] = finished_at
        execs.append(execution)
        _save("tool_executions.json", execs)
        return _err(
            "NOT_FOUND",
            f"Server '{qualifiedName}' is not active (status={server_status}) (rule: only active servers are routable)",
            error_code="SERVER_DISABLED",
            execution=execution,
        )

    # Resolve tool by name and active status for that server
    tool = None
    for t in tools:
        if not isinstance(t, dict):
            continue
        if t.get("server_id") == execution["server_id"] and t.get("name") == tool_name and t.get("status") == "active":
            tool = t
            break

    if tool is None:
        execution["status"] = "failed"
        execution["request_finished_at"] = finished_at
        execution["latency_ms"] = _lat_ms()
        execution["error_code"] = "TOOL_NOT_FOUND"
        execution["error_message"] = f"Tool '{tool_name}' not registered/active for server '{qualifiedName}'"
        execution["updated_at"] = finished_at
        execs.append(execution)
        _save("tool_executions.json", execs)
        return _err(
            "NOT_FOUND",
            f"Tool '{tool_name}' not registered/active for server '{qualifiedName}' (rule: parameters.name must match an active tool for the server)",
            error_code="TOOL_NOT_FOUND",
            execution=execution,
        )

    # Enforce tool_id belongs to same server
    if tool.get("server_id") != execution["server_id"]:
        execution["status"] = "failed"
        execution["request_finished_at"] = finished_at
        execution["latency_ms"] = _lat_ms()
        execution["error_code"] = "TOOL_NOT_FOUND"
        execution["error_message"] = "Resolved tool does not belong to resolved server"
        execution["updated_at"] = finished_at
        execs.append(execution)
        _save("tool_executions.json", execs)
        return _err(
            "CONFLICT",
            "Resolved tool does not belong to resolved server (rule: tool_id must belong to same server_id)",
            error_code="TOOL_NOT_FOUND",
            execution=execution,
        )

    execution["tool_id"] = tool.get("id")

    # Validate arguments against input_schema if present
    schema = tool.get("input_schema")
    ok, emsg = _validate_input_schema(schema, arguments)
    if not ok:
        execution["status"] = "failed"
        execution["request_finished_at"] = finished_at
        execution["latency_ms"] = _lat_ms()
        execution["error_code"] = "INVALID_ARGUMENTS"
        execution["error_message"] = emsg or "Arguments did not match input_schema"
        execution["updated_at"] = finished_at
        execs.append(execution)
        _save("tool_executions.json", execs)
        return _err(
            "VALIDATION_ERROR",
            f"Invalid arguments for tool '{tool_name}': {execution['error_message']} (rule: arguments must validate against tool input_schema when present)",
            error_code="INVALID_ARGUMENTS",
            execution=execution,
        )

    # At this point, record a succeeded execution with a minimal synthetic response (no upstream available offline).
    # Must still persist logs with consistent timestamps.
    finished_at = _iso(_now())
    execution["status"] = "succeeded"
    execution["request_finished_at"] = finished_at
    execution["latency_ms"] = _lat_ms()
    execution["response"] = {
        "ok": True,
        "server": {"id": execution["server_id"], "qualified_name": qualifiedName},
        "tool": {"id": execution["tool_id"], "name": tool_name},
        "echo": {"arguments": arguments},
    }
    execution["updated_at"] = finished_at
    execs.append(execution)
    _save("tool_executions.json", execs)

    return {"execution": execution, "response": execution["response"]}

def list_mcp_servers(status=None, tag=None, owner=None, transport=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0063000" if __import__("os").path.isdir("./environment_mix/0063000") else "/app/database")

    def _load(nm):
        try:
            with open(os.path.join(_DB, nm), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(nm, d):
        with open(os.path.join(_DB, nm), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_iso(dt):
        if not isinstance(dt, str) or not dt:
            return None
        try:
            if dt.endswith("Z"):
                return datetime.datetime.fromisoformat(dt[:-1])
            return datetime.datetime.fromisoformat(dt)
        except Exception:
            return None

    # Ambient auth: no explicit credential in this API; accept call as authenticated.
    # Validate filters
    valid_status = {"draft", "active", "deprecated", "disabled"}
    if status is not None:
        if not isinstance(status, str) or status not in valid_status:
            return _err("VALIDATION_ERROR", "Invalid status filter")
    if tag is not None and (not isinstance(tag, str) or tag.strip() == ""):
        return _err("VALIDATION_ERROR", "tag must be a non-empty string when provided")
    if owner is not None and (not isinstance(owner, str) or owner.strip() == ""):
        return _err("VALIDATION_ERROR", "owner must be a non-empty string when provided")
    valid_transport = {"http", "sse", "stdio"}
    if transport is not None:
        if not isinstance(transport, str) or transport not in valid_transport:
            return _err("VALIDATION_ERROR", "Invalid transport filter")
    if limit is None:
        lim = 20
    else:
        if not isinstance(limit, int) or isinstance(limit, bool):
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
        lim = limit
    valid_sort = {"created_at_desc", "created_at_asc", "updated_at_desc", "updated_at_asc", "qualified_name_asc"}
    if sort is None:
        sortv = "updated_at_desc"
    else:
        if not isinstance(sort, str) or sort not in valid_sort:
            return _err("VALIDATION_ERROR", "Invalid sort")
        sortv = sort

    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                return _err("VALIDATION_ERROR", "Invalid cursor")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor offset")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    servers = _load("mcp_servers.json")
    rows = [s for s in servers if isinstance(s, dict)]

    # Visibility/default exclude non-active unless status explicitly requested
    if status is None:
        rows = [s for s in rows if s.get("status") == "active"]
    else:
        rows = [s for s in rows if s.get("status") == status]

    if tag is not None:
        t = tag
        rows = [s for s in rows if isinstance(s.get("tags"), list) and t in s.get("tags")]
    if owner is not None:
        rows = [s for s in rows if s.get("owner") == owner]
    if transport is not None:
        rows = [s for s in rows if s.get("transport") == transport]

    def sort_key(s):
        if sortv == "qualified_name_asc":
            return (str(s.get("qualified_name") or ""),)
        if sortv.startswith("created_at"):
            dt = _parse_iso(s.get("created_at")) or datetime.datetime.min
            return (dt,)
        dt = _parse_iso(s.get("updated_at")) or datetime.datetime.min
        return (dt,)

    reverse = sortv.endswith("_desc")
    rows.sort(key=sort_key, reverse=reverse)

    total = len(rows)
    page = rows[offset : offset + lim]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8")

    return {
        "object": "toolbox.mcp_server_list",
        "data": page,
        "total": total,
        "limit": lim,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sortv,
    }

def create_mcp_server(qualified_name, transport, display_name=None, description=None, homepage_url=None, repo_url=None, endpoint_url=None, tags=None, icon_url=None, status=None, **_extra):
    import json, os, datetime, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0063000" if __import__("os").path.isdir("./environment_mix/0063000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int(time.time() * 1000)
        r = random.getrandbits(40)
        s = n ^ r
        out = []
        for _ in range(12):
            out.append(alphabet[s % 32])
            s //= 32
        return f"{prefix}_01J{''.join(reversed(out))}"

    # Validate required
    if not isinstance(qualified_name, str) or not qualified_name.strip():
        return _err("VALIDATION_ERROR", "qualified_name must be a non-empty string", field="qualified_name")
    if not isinstance(transport, str) or transport not in ("http", "sse", "stdio"):
        return _err("VALIDATION_ERROR", "transport must be one of: http, sse, stdio", field="transport")

    if status is None:
        status = "draft"
    if not isinstance(status, str) or status not in ("draft", "active", "deprecated", "disabled"):
        return _err("VALIDATION_ERROR", "status must be one of: draft, active, deprecated, disabled", field="status")

    # Enforce non-empty constraints if provided: schema requires display_name/description non-empty, but tool does not require them.
    # To be consistent with the datastore constraints, we must require them on create.
    if display_name is None or not isinstance(display_name, str) or not display_name.strip():
        return _err("VALIDATION_ERROR", "display_name is required and must be non-empty (constraint: display_name <> '')", field="display_name")
    if description is None or not isinstance(description, str) or not description.strip():
        return _err("VALIDATION_ERROR", "description is required and must be non-empty (constraint: description <> '')", field="description")

    # Optional fields types
    for fld, val in (("homepage_url", homepage_url), ("repo_url", repo_url), ("endpoint_url", endpoint_url), ("icon_url", icon_url)):
        if val is not None and not isinstance(val, str):
            return _err("VALIDATION_ERROR", f"{fld} must be a string", field=fld)

    # Tags
    if tags is None:
        tags = []
    if not isinstance(tags, list) or any((not isinstance(t, str)) for t in tags):
        return _err("VALIDATION_ERROR", "tags must be an array of strings", field="tags")

    # Transport/endpoint constraints
    if transport in ("http", "sse"):
        if endpoint_url is None or not isinstance(endpoint_url, str) or not endpoint_url.strip():
            return _err("VALIDATION_ERROR", "endpoint_url is required for http/sse transport (constraint)", field="endpoint_url")
    if transport == "stdio":
        if endpoint_url is not None:
            return _err("VALIDATION_ERROR", "endpoint_url must be null/omitted for stdio transport (constraint)", field="endpoint_url")

    # Load and enforce uniqueness(qualified_name)
    servers = _load("mcp_servers.json")
    if not isinstance(servers, list):
        servers = []
    for s in servers:
        if isinstance(s, dict) and s.get("qualified_name") == qualified_name:
            return _err("CONFLICT", f"qualified_name '{qualified_name}' is already in use (constraint: unique(qualified_name))", field="qualified_name")

    now = _now_iso()
    server_id = _gen_id("mcp_srv")

    row = {
        "id": server_id,
        "qualified_name": qualified_name,
        "display_name": display_name,
        "description": description,
        "homepage_url": homepage_url,
        "repo_url": repo_url,
        "transport": transport,
        "endpoint_url": endpoint_url,
        "tags": tags,
        "owner": None,
        "icon_url": icon_url,
        "status": status,
        "last_indexed_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Basic invariant checks for status/transport enums already enforced above; persist
    servers.append(row)
    _save("mcp_servers.json", servers)
    return {"server": row}

def update_mcp_server(id, display_name=None, description=None, homepage_url=None, repo_url=None, transport=None, endpoint_url=None, tags=None, owner=None, icon_url=None, status=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0063000" if __import__("os").path.isdir("./environment_mix/0063000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _is_str(x): return isinstance(x, str)
    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError("bad datetime")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        return datetime.datetime.fromisoformat(ss)

    try:
        if not _is_str(id) or not id.strip():
            return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

        if display_name is not None and (not _is_str(display_name) or display_name == ""):
            return _err("VALIDATION_ERROR", "display_name must be a non-empty string", field="display_name")
        if description is not None and (not _is_str(description) or description == ""):
            return _err("VALIDATION_ERROR", "description must be a non-empty string", field="description")
        for fn, v in [("homepage_url", homepage_url), ("repo_url", repo_url), ("owner", owner), ("icon_url", icon_url), ("endpoint_url", endpoint_url)]:
            if v is not None and not _is_str(v):
                return _err("VALIDATION_ERROR", f"{fn} must be a string", field=fn)
        if transport is not None:
            if not _is_str(transport):
                return _err("VALIDATION_ERROR", "transport must be a string", field="transport")
            if transport not in ("http", "sse", "stdio"):
                return _err("VALIDATION_ERROR", "transport must be one of: http, sse, stdio", field="transport")
        if tags is not None:
            if not isinstance(tags, list) or any((not isinstance(t, str)) for t in tags):
                return _err("VALIDATION_ERROR", "tags must be an array of strings", field="tags")
        if status is not None:
            if not _is_str(status):
                return _err("VALIDATION_ERROR", "status must be a string", field="status")
            if status not in ("draft", "active", "deprecated", "disabled"):
                return _err("VALIDATION_ERROR", "invalid status", field="status")

        servers = _load("mcp_servers.json")
        if not isinstance(servers, list):
            servers = []
        idx = None
        for i, s in enumerate(servers):
            if isinstance(s, dict) and s.get("id") == id:
                idx = i
                break
        if idx is None:
            return _err("NOT_FOUND", "MCP server not found", id=id)

        server = servers[idx]
        old_status = server.get("status")
        if old_status not in ("draft", "active", "deprecated", "disabled"):
            return _err("CONFLICT", "Stored server has invalid status", id=id, status=old_status)

        # Apply field updates
        if display_name is not None:
            server["display_name"] = display_name
        if description is not None:
            server["description"] = description
        if homepage_url is not None:
            server["homepage_url"] = homepage_url
        if repo_url is not None:
            server["repo_url"] = repo_url
        if owner is not None:
            server["owner"] = owner
        if icon_url is not None:
            server["icon_url"] = icon_url
        if tags is not None:
            server["tags"] = tags

        # Transport + endpoint logic
        if transport is not None:
            server["transport"] = transport
        if endpoint_url is not None:
            server["endpoint_url"] = endpoint_url

        # Validate transport/endpoint constraints against resulting record
        eff_transport = server.get("transport")
        eff_endpoint = server.get("endpoint_url")
        if eff_transport not in ("stdio", "http", "sse", "websocket", "unknown"):
            return _err("VALIDATION_ERROR", "transport invalid", field="transport")
        if eff_transport in ("http", "sse", "websocket"):
            if eff_endpoint is None:
                return _err("VALIDATION_ERROR", "endpoint_url is required for networked transports", field="endpoint_url")
            if not isinstance(eff_endpoint, str) or not eff_endpoint:
                return _err("VALIDATION_ERROR", "endpoint_url must be a non-empty string for networked transports", field="endpoint_url")
        if eff_transport == "stdio":
            if eff_endpoint is not None:
                return _err("VALIDATION_ERROR", "endpoint_url must be null for stdio transport", field="endpoint_url")

        # Validate required non-empty fields (constraints)
        if not isinstance(server.get("display_name"), str) or server.get("display_name") == "":
            return _err("VALIDATION_ERROR", "display_name must be non-empty", field="display_name")
        if not isinstance(server.get("description"), str) or server.get("description") == "":
            return _err("VALIDATION_ERROR", "description must be non-empty", field="description")
        if not isinstance(server.get("qualified_name"), str) or server.get("qualified_name") == "":
            return _err("CONFLICT", "Stored server has invalid qualified_name", id=id)

        # qualified_name immutability after activation: refuse changing it if server has ever been active.
        # (No qualified_name param in this tool; enforce by ensuring no external mutation path here.)
        # Still, defend against stored state anomalies by checking activation history flag if present.
        ever_active = server.get("ever_activated")
        if ever_active is True and server.get("qualified_name") != servers[idx].get("qualified_name"):
            return _err("INVALID_TRANSITION", "qualified_name is immutable after activation", field="qualified_name")

        # Unique qualified_name constraint (unchanged here, but enforce in case of datastore anomalies)
        qn = server.get("qualified_name")
        for s in servers:
            if isinstance(s, dict) and s.get("id") != id and s.get("qualified_name") == qn:
                return _err("CONFLICT", "qualified_name must be unique", field="qualified_name", qualified_name=qn)

        # Lifecycle transition
        if status is not None and status != old_status:
            transitions = {
                "draft": ("active", "disabled"),
                "active": ("deprecated", "disabled"),
                "deprecated": ("active", "disabled"),
                "disabled": ("active",),
            }
            allowed = transitions.get(old_status, ())
            if status not in allowed:
                return _err("INVALID_TRANSITION", "Invalid lifecycle transition", from_status=old_status, to_status=status)

            server["status"] = status
            if status == "active":
                # lock qualified_name from this point forward
                server["ever_activated"] = True

        # Update timestamps
        now = _now()
        if not isinstance(server.get("created_at"), str) or not server.get("created_at"):
            server["created_at"] = now
        # Ensure created_at parseable; if not, normalize
        try:
            _parse_dt(server.get("created_at"))
        except Exception:
            server["created_at"] = now
        server["updated_at"] = now

        servers[idx] = server
        _save("mcp_servers.json", servers)

        return {"server": server}
    except (ValueError, TypeError) as e:
        return _err("VALIDATION_ERROR", "Invalid input", details=str(e))
    except Exception as e:
        return _err("CONFLICT", "Unexpected error", details=str(e))

def list_tool_executions(server_id=None, qualified_name=None, tool_id=None, tool_name=None, status=None, created_after=None, created_before=None, include_response=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0063000" if __import__("os").path.isdir("./environment_mix/0063000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _parse_rfc3339_lenient(s):
        # Accept strict RFC3339, but also accept arbitrary strings by treating them as non-parsable (no filter),
        # because caller args may contain ids (audit defect) and should not hard error for list.
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, "not_string"
        ss = s.strip()
        if not ss:
            return None, "empty"
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt, None
        except ValueError:
            return None, "parse_error"

    def _b64d(s):
        pad = "=" * (-len(s) % 4)
        return base64.urlsafe_b64decode((s + pad).encode("utf-8")).decode("utf-8")

    def _b64e(s):
        return base64.urlsafe_b64encode(s.encode("utf-8")).decode("utf-8").rstrip("=")

    # Validate types (but do not over-validate timestamp formats; treat unparseable as "no time filter")
    for fn, v in [("server_id", server_id), ("qualified_name", qualified_name), ("tool_id", tool_id), ("tool_name", tool_name), ("cursor", cursor), ("sort", sort)]:
        if v is not None and not isinstance(v, str):
            return _err("VALIDATION_ERROR", f"{fn} must be a string", field=fn)

    if status is not None:
        if not isinstance(status, str) or status not in ("queued", "running", "succeeded", "failed", "cancelled"):
            return _err("VALIDATION_ERROR", "status must be one of queued, running, succeeded, failed, cancelled", field="status")

    if include_response is None:
        include_response_v = False
    else:
        if not isinstance(include_response, bool):
            return _err("VALIDATION_ERROR", "include_response must be a boolean", field="include_response")
        include_response_v = include_response

    if limit is None:
        limit_v = 20
    else:
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100", field="limit")
        limit_v = limit

    if sort is None:
        sort_v = "created_at_desc"
    else:
        if sort not in ("created_at_desc", "created_at_asc"):
            return _err("VALIDATION_ERROR", "sort must be one of created_at_desc, created_at_asc", field="sort")
        sort_v = sort

    created_after_dt, _ = _parse_rfc3339_lenient(created_after)
    created_before_dt, _ = _parse_rfc3339_lenient(created_before)

    execs = _load("tool_executions.json")
    if not isinstance(execs, list):
        execs = []

    # Filter
    out = []
    for r in execs:
        if not isinstance(r, dict):
            continue
        if server_id is not None and r.get("server_id") != server_id:
            continue
        if qualified_name is not None and r.get("qualified_name") != qualified_name:
            continue
        if tool_id is not None and r.get("tool_id") != tool_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if status is not None and r.get("status") != status:
            continue

        # Time filters only if parsable
        if created_after_dt is not None or created_before_dt is not None:
            ca = r.get("created_at")
            if isinstance(ca, str):
                ca_dt, err = _parse_rfc3339_lenient(ca)
            else:
                ca_dt, err = (None, "missing")
            if ca_dt is None:
                # If we can't parse stored created_at, do not exclude it based on time filters.
                pass
            else:
                if created_after_dt is not None and not (ca_dt > created_after_dt):
                    continue
                if created_before_dt is not None and not (ca_dt < created_before_dt):
                    continue

        out.append(r)

    # Sort
    def _key_dt(rec):
        v = rec.get("created_at")
        if not isinstance(v, str):
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        dt, err = _parse_rfc3339_lenient(v)
        return dt if dt is not None else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    reverse = (sort_v == "created_at_desc")
    out.sort(key=_key_dt, reverse=reverse)

    # Cursor pagination (opaque)
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")
        token = cursor
        decoded = None
        try:
            decoded = _b64d(token)
        except (ValueError, UnicodeDecodeError):
            decoded = None
        # Accept either base64("id:<exec_id>") or raw exec_id
        cur_id = None
        if decoded and decoded.startswith("id:"):
            cur_id = decoded[3:]
        else:
            cur_id = token
        # start after this id if present
        for i, r in enumerate(out):
            if r.get("id") == cur_id:
                start = i + 1
                break

    page = out[start:start + limit_v]
    next_cursor = None
    has_more = (start + limit_v) < len(out)
    if has_more and page:
        next_cursor = _b64e("id:" + str(page[-1].get("id")))

    # Drop response if not requested
    if not include_response_v:
        page = [dict({k: v for k, v in rec.items() if k != "response"}) for rec in page]

    return {
        "executions": page,
        "total": len(out),
        "has_more": has_more,
        "next_cursor": next_cursor,
        "limit": limit_v,
        "sort": sort_v,
    }

def cancel_tool_execution(id, reason=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0063000" if __import__("os").path.isdir("./environment_mix/0063000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "reason must be a string", field="reason")

    executions = _load("tool_executions.json")
    if not isinstance(executions, list):
        executions = []

    ex = None
    idx = None
    for i, r in enumerate(executions):
        if isinstance(r, dict) and r.get("id") == id:
            ex = r
            idx = i
            break
    if ex is None:
        return _err("NOT_FOUND", "Tool execution not found", id=id)

    allowed = {
        "queued": {"running", "cancelled", "failed"},
        "running": {"succeeded", "failed", "cancelled"},
        "succeeded": set(),
        "failed": set(),
        "cancelled": set(),
    }
    st = ex.get("status")
    if st not in allowed:
        return _err("CONFLICT", "Stored execution has invalid status", id=id, status=st)

    # Idempotent for terminal states
    if st in ("succeeded", "failed", "cancelled"):
        return {"execution": ex}

    if "cancelled" not in allowed.get(st, set()):
        return _err("INVALID_TRANSITION", "Invalid lifecycle transition", from_status=st, to_status="cancelled")

    now = _now_iso()
    ex["status"] = "cancelled"
    ex["updated_at"] = now
    ex["request_finished_at"] = now

    # Store cancellation reason if a field exists or can be added without breaking constraints.
    # Schema does not define it; keep it under response metadata to avoid unknown top-level columns assumptions.
    if reason is not None and reason.strip():
        resp = ex.get("response")
        if resp is None or not isinstance(resp, dict):
            resp = {}
        meta = resp.get("_meta")
        if meta is None or not isinstance(meta, dict):
            meta = {}
        meta["cancellation_reason"] = reason
        resp["_meta"] = meta
        ex["response"] = resp

    # latency_ms: compute if possible, else keep existing, else set to 0
    started = _parse_iso(ex.get("request_started_at"))
    finished = _parse_iso(now)
    if started and finished:
        ms = int((finished - started).total_seconds() * 1000)
        ex["latency_ms"] = ms if ms >= 0 else 0
    else:
        if ex.get("latency_ms") is None:
            ex["latency_ms"] = 0

    executions[idx] = ex
    _save("tool_executions.json", executions)
    return {"execution": ex}
